cd /tmp && cat > /tmp/snap.php <<'EOF'
<?php
$pdo = new PDO('pgsql:host=postgres;dbname=llmapi_eval', 'eval_rw', 'eval_rw', [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
$mode = $argv[1];
if ($mode === 'save') {
  $stock = $pdo->query('select id, title, price_cents, stock from book order by id')->fetchAll(PDO::FETCH_ASSOC);
  $maxp = $pdo->query('select coalesce(max(id),0) from purchase')->fetchColumn();
  file_put_contents('/tmp/snapshot.json', json_encode(['stock'=>$stock,'maxp'=>(int)$maxp]));
  echo "saved max purchase $maxp\n";
} else {
  $s = json_decode(file_get_contents('/tmp/snapshot.json'), true);
  $pdo->beginTransaction();
  $pdo->exec("delete from purchase_line where purchase_id > {$s['maxp']}");
  $pdo->exec("delete from purchase where id > {$s['maxp']}");
  foreach ($s['stock'] as $b) {
    $pdo->prepare('update book set stock=?, title=?, price_cents=? where id=?')->execute([$b['stock'], $b['title'], $b['price_cents'], $b['id']]);
  }
  $pdo->commit();
  echo "restored\n";
}
EOF
